import every from"lodash/every";import isString from"lodash/isString";import pickBy from"lodash/pickBy";import assign from"lodash/assign";import parameterize from"./parameterize.mjs";export class Utils{constructor(profile){this.profile=profile;this.url=this.url.bind(this);this.imageUrlBuilder=this.imageUrlBuilder.bind(this);this.imageURLWithParams=this.imageURLWithParams.bind(this)}extend(profile){if(!profile||typeof profile!=="object")throw new TypeError("Expected profile to be an object");this.profile=Object.assign({},this.profile,profile)}url(){let path=arguments.length>0&&arguments[0]!==undefined?arguments[0]:"";let o=this.profile;return o.protocol+"://"+o.domain+o.port+o[path]}imageUrlBuilder(imageDomain,requiredParam,paramsObject){try{const stringParams=pickBy(paramsObject,isString);if(!stringParams[requiredParam]&&every(stringParams,isString)){throw new TypeError("Missing required params or wrong types")}const p=parameterize(assign({domain:imageDomain},stringParams));return`${this.url("images")}${p}`.replace(/\s/gi,"-").toLowerCase()}catch(e){console.warn(e)}}imageURLWithParams(paramsString){let type=arguments.length>1&&arguments[1]!==undefined?arguments[1]:"thumbnail";try{if(!paramsString||typeof paramsString!=="string"){throw new TypeError("Missing URL paramsString, empty or not a string")}return`${this.url("images")}?${paramsString}&type=${type}`}catch(e){console.warn(e)}}}